// Local development: copy this file to config.js and fill in your values.
// config.js is gitignored. On Netlify it is generated by netlify-build.sh
// from the SUPABASE_URL / SUPABASE_ANON_KEY environment variables.
// Leave the values empty (or delete config.js) to play fully offline.
window.DW_CONFIG = {
  supabaseUrl: 'https://YOUR-PROJECT-REF.supabase.co',
  supabaseAnonKey: 'your-anon-public-key',
  // Raids require a GPS lock to engage. Set false only for desk testing.
  raidRequireGps: true,
  // Map streets. CARTO's dark tiles need a free API key (no account needed):
  // request one at https://carto.com/basemaps/apikey, restrict it to your site
  // (e.g. stalwart-mermaid-b3cfaf.netlify.app and *--stalwart-mermaid-b3cfaf.netlify.app
  // for previews; a separate key for localhost), and paste it here. On Netlify set the
  // CARTO_KEY environment variable instead. Leave it empty to use OpenStreetMap's
  // standard tiles (fine for testing; their policy allows light use only).
  cartoKey: '',
  // In-game "✉ SEND FEEDBACK" (under ☰ MORE). Where tester reports go:
  //   ''  (the default)                 → the built-in tester form, feedback.html (a Netlify Form;
  //                                       read answers in Netlify under Forms → tester-feedback).
  //                                       The Android/iOS app opens it on the live site in the browser.
  //   'mailto:you@yourdomain'           → opens an email to you with the report filled in
  //   'https://forms.gle/…' or any URL  → opens that page; {body} and {subject} in the URL
  //                                       are replaced with the report text
  // On Netlify set the FEEDBACK_URL environment variable instead.
  feedbackUrl: '',
};
